$ErrorActionPreference='Stop'; Add-Type -AssemblyName System.Security; Add-Type -AssemblyName System.Data
$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot); $cfg=Join-Path $root 'LavaFacil.Web\Data\connection.dpapi'; $b=[Security.Cryptography.ProtectedData]::Unprotect([IO.File]::ReadAllBytes($cfg),$null,[Security.Cryptography.DataProtectionScope]::CurrentUser); $s=[Text.Encoding]::UTF8.GetString($b).Replace('Trust Server Certificate','TrustServerCertificate').Replace('Encrypt=Mandatory','Encrypt=True'); $c=New-Object System.Data.SqlClient.SqlConnection((New-Object System.Data.SqlClient.SqlConnectionStringBuilder $s).ConnectionString); $c.Open(); $q=$c.CreateCommand(); $q.CommandText="SELECT (SELECT COUNT(*) FROM dbo.Usuarios WHERE NombreUsuario LIKE 'autotest.%') AS U,(SELECT COUNT(*) FROM dbo.Clientes WHERE Email LIKE 'autotest.%') AS C"; $r=$q.ExecuteReader(); $r.Read(); "before U=$($r.GetInt32(0)) C=$($r.GetInt32(1))"; $r.Close(); $q.CommandText="DELETE t FROM dbo.TokensCorreo t JOIN dbo.Usuarios u ON u.IdUsuario=t.IdUsuario WHERE u.NombreUsuario LIKE 'autotest.correo.%' OR u.NombreUsuario LIKE 'autotest.api.test%' OR u.NombreUsuario LIKE 'autotest.cookie.%'; DELETE FROM dbo.Usuarios WHERE NombreUsuario LIKE 'autotest.%'; DELETE FROM dbo.Clientes WHERE Email LIKE 'autotest.%';"; [void]$q.ExecuteNonQuery(); $q.CommandText="SELECT (SELECT COUNT(*) FROM dbo.Usuarios WHERE NombreUsuario LIKE 'autotest.%') AS U,(SELECT COUNT(*) FROM dbo.Clientes WHERE Email LIKE 'autotest.%') AS C"; $r=$q.ExecuteReader(); $r.Read(); "after U=$($r.GetInt32(0)) C=$($r.GetInt32(1))"; $r.Close(); $c.Dispose()




